/**
 * WebCodecs 非实时视频压缩。
 *
 * 与 MediaRecorder 的实时录制不同，这里直接把 MP4 解封装后交给 VideoDecoder / VideoEncoder
 * 按 CPU 速度跑满，不需要等视频播放完，短视频通常 1–3 秒即可完成。
 *
 * 链路：mp4box 解封装 → VideoDecoder 解码 → canvas 缩放 → VideoEncoder 重新编码 H.264
 *      → 音频 AAC 原始样本直接复用（不重编码） → mp4-muxer 封装。
 *
 * 只处理浏览器可解的 H.264/AAC MP4（含 MOV/m4v）。其他容器或编码返回 unsupported，
 * 由调用方回退到 MediaRecorder 实时录制。
 */
import * as MP4BoxModule from 'mp4box';
import { Muxer, ArrayBufferTarget } from 'mp4-muxer';
import { resolveLivePhotoVideoBitrate } from '@/utils/upload/livePhotoSettings';

const createMp4File = MP4BoxModule.createFile || MP4BoxModule.default?.createFile;
const US = 1_000_000;

const ENCODER_CODECS = ['avc1.640028', 'avc1.4d0028', 'avc1.42001f'];
const AAC_RATES = [96000, 88200, 64000, 48000, 44100, 32000, 24000, 22050, 16000, 12000, 11025, 8000, 7350];

export function isWebCodecsVideoSupported() {
    return typeof VideoDecoder !== 'undefined'
        && typeof VideoEncoder !== 'undefined'
        && typeof VideoFrame !== 'undefined'
        && typeof EncodedVideoChunk !== 'undefined'
        && typeof createMp4File === 'function';
}

function even(value) {
    return Math.max(2, Math.round(value / 2) * 2);
}

/** 从 mp4box 的 avcC 配置盒构造 VideoDecoder 需要的 AVCDecoderConfigurationRecord */
export function buildAvcDescription(avcC) {
    if (!avcC || !Array.isArray(avcC.SPS) || !avcC.SPS.length) return null;
    const parts = [];
    parts.push(new Uint8Array([
        1,
        avcC.AVCProfileIndication,
        avcC.profile_compatibility,
        avcC.AVCLevelIndication,
        (avcC.lengthSizeMinusOne ?? 3) | 0xfc,
        (avcC.SPS.length & 0x1f) | 0xe0,
    ]));
    for (const sps of avcC.SPS) {
        const nalu = new Uint8Array(sps.nalu || sps.data || []);
        const head = new Uint8Array([(nalu.length >> 8) & 0xff, nalu.length & 0xff]);
        parts.push(head, nalu);
    }
    const pps = avcC.PPS || [];
    parts.push(new Uint8Array([pps.length & 0xff]));
    for (const item of pps) {
        const nalu = new Uint8Array(item.nalu || item.data || []);
        parts.push(new Uint8Array([(nalu.length >> 8) & 0xff, nalu.length & 0xff]), nalu);
    }
    if (avcC.ext?.length) parts.push(new Uint8Array(avcC.ext));
    const total = parts.reduce((sum, part) => sum + part.length, 0);
    const result = new Uint8Array(total);
    let offset = 0;
    for (const part of parts) {
        result.set(part, offset);
        offset += part.length;
    }
    return result;
}

/** 递归找 ES_Descriptor 里的 DecoderSpecificInfo（tag 5），即 AudioSpecificConfig */
function findDecoderSpecificInfo(desc) {
    if (!desc) return null;
    if (desc.tag === 5 && desc.data?.length) return new Uint8Array(desc.data);
    for (const child of desc.descs || []) {
        const found = findDecoderSpecificInfo(child);
        if (found) return found;
    }
    return null;
}

export function buildAacDescription(audioTrack, audioEntry) {
    const fromEsds = findDecoderSpecificInfo(audioEntry?.esds?.esd);
    if (fromEsds) return fromEsds;
    const sampleRate = Math.round(audioTrack.audio?.sample_rate || audioTrack.sample_rate || 44100);
    const channels = audioTrack.audio?.channel_count || audioTrack.channel_count || 2;
    const rateIndex = AAC_RATES.indexOf(sampleRate);
    const bits = (2 << 11) | ((rateIndex >= 0 ? rateIndex : 15) << 7) | (Math.min(channels, 7) << 3);
    return new Uint8Array([(bits >> 8) & 0xff, bits & 0xff]);
}

/** mp4box 同步解析：返回轨道信息、样本与配置盒 */
export function demux(arrayBuffer) {
    if (!createMp4File) throw new Error('mp4box is unavailable');
    const file = createMp4File();
    let info = null;
    let parseError = null;
    file.onReady = (readyInfo) => { info = readyInfo; };
    file.onError = (error) => { parseError = error; };

    // ArrayBuffer 需要带 fileStart 供 mp4box 定位样本偏移
    arrayBuffer.fileStart = 0;
    file.appendBuffer(arrayBuffer);
    file.flush();
    if (parseError) throw new Error(String(parseError));
    if (!info || !info.videoTracks?.length) throw new Error('No video track found');

    const videoTrack = info.videoTracks[0];
    const audioTrack = info.audioTracks?.[0] || null;
    const videoEntry = file.getTrackById(videoTrack.id)?.mdia?.minf?.stbl?.stsd?.entries?.[0];
    const audioEntry = audioTrack
        ? file.getTrackById(audioTrack.id)?.mdia?.minf?.stbl?.stsd?.entries?.[0]
        : null;

    const byId = {};
    file.onSamples = (id, user, samples) => {
        byId[id] = (byId[id] || []).concat(samples);
    };
    file.setExtractionOptions(videoTrack.id, null, { nbSamples: 1000000 });
    if (audioTrack) file.setExtractionOptions(audioTrack.id, null, { nbSamples: 1000000 });
    file.start();

    return {
        videoTrack,
        audioTrack,
        videoEntry,
        audioEntry,
        videoSamples: byId[videoTrack.id] || [],
        audioSamples: audioTrack ? (byId[audioTrack.id] || []) : [],
    };
}

/**
 * 少数浏览器不会在 VideoEncoder 的 output meta 里给出 avcC。
 * 此时从首个关键帧的 AVCC 数据里解析 SPS/PPS，补出一个 decoderConfig.description，
 * 否则 mp4-muxer 在 finalize() 时无法生成 avc1 样本描述。
 */
function avcCFromKeyChunk(chunk) {
    const data = new Uint8Array(chunk.byteLength);
    chunk.copyTo(data);
    const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
    const sps = [];
    const pps = [];
    let profile = 100;
    let compat = 0;
    let level = 31;
    let offset = 0;
    while (offset + 4 <= data.length) {
        const length = view.getUint32(offset);
        offset += 4;
        if (length <= 0 || offset + length > data.length) break;
        const nalu = data.subarray(offset, offset + length);
        offset += length;
        const type = nalu[0] & 0x1f;
        if (type === 7) {
            sps.push({ nalu });
            profile = nalu[1];
            compat = nalu[2];
            level = nalu[3];
        } else if (type === 8) {
            pps.push({ nalu });
        } else if (sps.length) {
            break;
        }
    }
    if (!sps.length) return null;
    return buildAvcDescription({
        AVCProfileIndication: profile,
        profile_compatibility: compat,
        AVCLevelIndication: level,
        lengthSizeMinusOne: 3,
        SPS: sps,
        PPS: pps,
    });
}

function resolveBitrate(settings, durationSeconds, width, height) {
    const base = resolveLivePhotoVideoBitrate(settings, durationSeconds);
    const scale = Math.max(0.6, Math.min(2.5, (width * height) / (1280 * 720)));
    return Math.round(Math.min(8_000_000, Math.max(300_000, base * scale)));
}

/**
 * @param {File} file 源视频（MP4/MOV，H.264）
 * @param {{rate:number,targetSize:number,maxEdge:number}} options
 * @returns {{file:File, compressed:boolean, reason:string, before?:number, after?:number}}
 */
export async function compressVideoWithWebCodecs(file, options = {}) {
    const fallback = (reason) => ({ file, compressed: false, reason });
    if (!isWebCodecsVideoSupported()) return fallback('unsupported');

    let demuxed;
    try {
        demuxed = demux(await file.arrayBuffer());
    } catch (error) {
        console.warn('WebCodecs: could not demux the source video:', error);
        return fallback('unsupported');
    }

    const { videoTrack, audioTrack, videoEntry, audioEntry, videoSamples, audioSamples } = demuxed;
    if (!videoSamples.length) return fallback('unsupported');
    // 只处理 H.264（avcC 配置）；HEVC/AV1/VP9 交给实时录制回退，避免产出损坏文件。
    if (!/^avc[13]\./i.test(videoTrack.codec || '')) return fallback('unsupported');
    // 音频只直拷 AAC-LC；其他音频编码回退实时录制，避免丢声音或写错 AudioSpecificConfig。
    if (audioTrack && !/^mp4a\.40\.2/i.test(audioTrack.codec || '')) return fallback('unsupported');
    const description = buildAvcDescription(videoEntry?.avcC);
    if (!description) return fallback('unsupported');

    const sourceWidth = videoTrack.video?.width || videoTrack.track_width;
    const sourceHeight = videoTrack.video?.height || videoTrack.track_height;
    if (!sourceWidth || !sourceHeight) return fallback('unsupported');

    const settings = { rate: 75, targetSize: 0, maxEdge: 1280, ...options };
    const scale = Math.min(1, settings.maxEdge / Math.max(sourceWidth, sourceHeight));
    const width = even(sourceWidth * scale);
    const height = even(sourceHeight * scale);
    const trackDuration = videoTrack.duration / videoTrack.timescale;
    const fps = Math.max(1, Math.min(60, videoSamples.length / (trackDuration || 1)));

    let encoderConfig;
    for (const codec of ENCODER_CODECS) {
        const candidate = {
            codec, width, height,
            bitrate: resolveBitrate(settings, trackDuration, width, height),
            framerate: fps,
            avc: { format: 'avc' },
            latencyMode: 'quality',
        };
        try {
            const support = await VideoEncoder.isConfigSupported(candidate);
            if (support?.supported) {
                encoderConfig = support.config || candidate;
                break;
            }
        } catch (error) {
            console.warn('WebCodecs: encoder config not supported:', codec, error);
        }
    }
    if (!encoderConfig) return fallback('unsupported');

    const target = new ArrayBufferTarget();
    const muxer = new Muxer({
        target,
        video: { codec: 'avc', width, height, frameRate: fps },
        audio: audioTrack ? {
            codec: 'aac',
            numberOfChannels: audioTrack.audio?.channel_count || 2,
            sampleRate: Math.round(audioTrack.audio?.sample_rate || 44100),
        } : undefined,
        fastStart: 'in-memory',
    });

    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return fallback('unsupported');

    let decodeError = null;
    let encodeError = null;
    let frameIndex = 0;
    let encoder;

    const decoder = new VideoDecoder({
        output(frame) {
            try {
                ctx.drawImage(frame, 0, 0, width, height);
                // 用连续时间戳重排输出，避免源 B 帧的 cts/dts 偏移让 muxer 收到乱序 chunk
                const scaled = new VideoFrame(canvas, {
                    timestamp: Math.round(frameIndex * US / fps),
                    duration: Math.round(US / fps),
                });
                encoder.encode(scaled, { keyFrame: frameIndex % Math.max(1, Math.round(fps * 2)) === 0 });
                scaled.close();
                frameIndex++;
            } catch (error) {
                encodeError = error;
            } finally {
                frame.close();
            }
        },
        error(error) { decodeError = error; },
    });

    let fallbackAvcC = null;
    encoder = new VideoEncoder({
        output(chunk, meta) {
            let safeMeta = meta;
            if (!meta?.decoderConfig?.description) {
                if (!fallbackAvcC) fallbackAvcC = avcCFromKeyChunk(chunk);
                if (fallbackAvcC) {
                    safeMeta = {
                        decoderConfig: {
                            codec: encoderConfig.codec,
                            codedWidth: width,
                            codedHeight: height,
                            description: fallbackAvcC,
                        },
                    };
                }
            }
            muxer.addVideoChunk(chunk, safeMeta);
        },
        error(error) { encodeError = error; },
    });

    try {
        decoder.configure({
            codec: videoTrack.codec,
            codedWidth: sourceWidth,
            codedHeight: sourceHeight,
            description,
            optimizeForLatency: false,
        });
        encoder.configure(encoderConfig);

        for (let i = 0; i < videoSamples.length; i++) {
            const sample = videoSamples[i];
            if (decodeError || encodeError) throw decodeError || encodeError;
            decoder.decode(new EncodedVideoChunk({
                type: sample.is_sync ? 'key' : 'delta',
                // 解码顺序按 dts；时间戳仅用于排序，输出统一由 frameIndex 重建
                timestamp: Math.round((sample.dts - (videoSamples[0]?.dts || 0)) * US / sample.timescale),
                duration: Math.round(sample.duration * US / sample.timescale),
                data: new Uint8Array(sample.data),
            }));
            // 每隔一批排空编码队列，避免大视频把编码器队列撑爆
            if (i % 30 === 29) await encoder.flush();
        }
        await decoder.flush();
        await encoder.flush();
        if (decodeError || encodeError) throw decodeError || encodeError;
        if (!frameIndex) return fallback('decode-failed');

        if (audioTrack && audioSamples.length) {
            const audioMeta = {
                decoderConfig: {
                    codec: audioTrack.codec || 'mp4a.40.2',
                    sampleRate: Math.round(audioTrack.audio?.sample_rate || 44100),
                    numberOfChannels: audioTrack.audio?.channel_count || 2,
                    description: buildAacDescription(audioTrack, audioEntry),
                },
            };
            const audioStart = audioSamples[0]?.cts || 0;
            for (const sample of audioSamples) {
                muxer.addAudioChunkRaw(
                    new Uint8Array(sample.data),
                    'key',
                    Math.round((sample.cts - audioStart) * US / sample.timescale),
                    Math.round(sample.duration * US / sample.timescale),
                    audioMeta,
                );
            }
        }

        muxer.finalize();
        const output = new Uint8Array(target.buffer);
        if (!output.length || output.length >= file.size * 0.92) return fallback('no-gain');

        const outputName = String(file.name || 'video').replace(/\.[^.]+$/, '') + '.mp4';
        const compressedFile = new File([output], outputName, {
            type: 'video/mp4',
            lastModified: file.lastModified,
        });
        return {
            file: compressedFile,
            compressed: true,
            reason: 'compressed',
            before: file.size,
            after: compressedFile.size,
        };
    } catch (error) {
        console.warn('WebCodecs compression failed, falling back:', error);
        return fallback(decodeError ? 'decode-failed' : 'encode-failed');
    } finally {
        try { decoder.close(); } catch { /* already closed */ }
        try { encoder.close(); } catch { /* already closed */ }
    }
}
